import os, glob
RLM_SESSION_DIR = os.environ.get('RLM_SESSION_DIR', '')
sessions_folder = os.path.join(RLM_SESSION_DIR, '..', '..', 'sessions')
if os.path.exists(sessions_folder):
    print("Sessions folder contents:")
    for f in os.listdir(sessions_folder):
        path = os.path.join(sessions_folder, f)
        if os.path.isfile(path):
            size = os.path.getsize(path)
            print(f"  {f}: {size} bytes")
else:
    print("Sessions folder not found")

